public async Task UpdateProductAsync(Product updated, CancellationToken ct)
{
    await _dbContext.Products.ExecuteUpdateAsync(s => s
        .SetProperty(p => p.Name, updated.Name)
        .SetProperty(p => p.Price, updated.Price)
        .Where(p => p.Id == updated.Id), ct);

    var redis = _redis.GetDatabase();
    var cacheKey = $"product:{updated.Id}:details";
    await redis.KeyDeleteAsync(cacheKey);
}

